uint32_t SDMMC_DMALinkedList_UnlockNode(SDMMC_DMALinkNodeTypeDef *pNode)
{

  if (pNode == NULL)
  {
    return SDMMC_ERROR_INVALID_PARAMETER;
  }

  MODIFY_REG(pNode->IDMALAR, SDMMC_IDMALAR_ABR, SDMMC_IDMALAR_ABR);

  return SDMMC_ERROR_NONE;
}

